import { useState } from "react";
import S from "../utils/storage";
import C from "../constants/colors";
import { CROPS_ALL, STATES_TN_DISTRICTS } from "../constants/crops";
import Input from "../components/ui/Input";
import Btn from "../components/ui/Btn";

function AuthPage({ onLogin }) {
  const [mode, setMode] = useState("login");
  const [form, setForm] = useState({ name:"", phone:"", password:"", confirm:"", district:"Madurai", state:"Tamil Nadu", landSize:"", crops:[] });
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);

  const f = (k) => (e) => setForm(p => ({ ...p, [k]: e.target.value }));

  const handleLogin = () => {
    setErr("");
    if (!form.phone || !form.password) return setErr("Phone and password required");
    const users = S.get("users") || [];
    const found = users.find(u => u.phone === form.phone && u.password === form.password);
    if (!found) return setErr("Invalid phone number or password");
    S.set("current_user", found);
    onLogin(found);
  };

  const handleRegister = () => {
    if (step === 1) {
      if (!form.name || !form.phone || !form.password) return setErr("All fields required");
      if (form.phone.length < 10) return setErr("Enter valid 10-digit mobile number");
      if (form.password !== form.confirm) return setErr("Passwords do not match");
      if (form.password.length < 6) return setErr("Password must be at least 6 characters");
      const users = S.get("users") || [];
      if (users.find(u => u.phone === form.phone)) return setErr("Phone already registered. Please login.");
      setErr(""); setStep(2);
    } else {
      setLoading(true);
      const users = S.get("users") || [];
      const newUser = {
        id: Date.now().toString(), name:form.name, phone:form.phone, password:form.password,
        district:form.district, state:form.state, landSize:parseFloat(form.landSize)||0,
        crops:form.crops, lat:9.9252, lon:78.1198,
        farms:[], cropHistory:[], diseaseHistory:[],
        language:"Tamil", createdAt:new Date().toISOString(),
      };
      users.push(newUser);
      S.set("users", users);
      S.set("current_user", newUser);
      setTimeout(() => { setLoading(false); onLogin(newUser); }, 800);
    }
  };

  const cropToggle = (c) => setForm(p => ({ ...p, crops: p.crops.includes(c) ? p.crops.filter(x=>x!==c) : [...p.crops, c] }));

  return (
    <div style={{ minHeight:"100vh", background:`linear-gradient(145deg,${C.dark} 0%,${C.bg1} 50%,#0a4020 100%)`, display:"flex", alignItems:"center", justifyContent:"center", padding:16 }}>
      <div style={{ width:"100%", maxWidth:420 }}>
        <div style={{ textAlign:"center", marginBottom:24 }}>
          <div style={{ fontSize:48, marginBottom:8 }}>🌿</div>
          <div style={{ color:"#fff", fontSize:26, fontWeight:700, letterSpacing:"-0.02em" }}>Agro Zenith</div>
          <div style={{ color:"rgba(255,255,255,0.5)", fontSize:13, marginTop:3 }}>Empowering Agriculture · Predicting Harvests</div>
        </div>

        <div style={{ background:"rgba(255,255,255,0.96)", borderRadius:16, padding:28, boxShadow:"0 20px 60px rgba(0,0,0,0.3)" }}>
          <div style={{ display:"flex", marginBottom:22, background:C.bg, borderRadius:10, padding:3 }}>
            {["login","register"].map(m => (
              <button key={m} onClick={() => { setMode(m); setErr(""); setStep(1); }} style={{
                flex:1, padding:"9px", borderRadius:8, fontSize:13.5, fontWeight:500, cursor:"pointer",
                background:mode===m?C.white:"transparent", color:mode===m?C.text:C.muted,
                border:"none", boxShadow:mode===m?"0 1px 4px rgba(0,0,0,0.1)":"none", transition:"all 0.2s",
              }}>{m === "login" ? "🔑 Login" : "✨ Register"}</button>
            ))}
          </div>

          {err && <div style={{ background:C.redPale, color:C.red, padding:"10px 12px", borderRadius:8, fontSize:13, marginBottom:14, border:`1px solid #f5c6c6` }}>⚠️ {err}</div>}

          {mode === "login" ? (
            <>
              <Input label="Mobile Number" type="tel" value={form.phone} onChange={f("phone")} placeholder="10-digit mobile number" required />
              <Input label="Password" type="password" value={form.password} onChange={f("password")} placeholder="Enter password" required />
              <Btn onClick={handleLogin} style={{ width:"100%", padding:12, fontSize:15 }}>Login to Agro Zenith →</Btn>
              <div style={{ textAlign:"center", marginTop:14, fontSize:12, color:C.muted }}>New farmer? <span onClick={() => setMode("register")} style={{ color:C.bg2, cursor:"pointer", fontWeight:500 }}>Register here</span></div>
            </>
          ) : step === 1 ? (
            <>
              <div style={{ fontSize:12.5, color:C.muted, marginBottom:14, padding:"8px 12px", background:C.pale, borderRadius:7 }}>📱 Step 1 of 2 — Personal Details</div>
              <Input label="Full Name" value={form.name} onChange={f("name")} placeholder="Your name" required />
              <Input label="Mobile Number" type="tel" value={form.phone} onChange={f("phone")} placeholder="10-digit number (used as login ID)" required />
              <Input label="Create Password" type="password" value={form.password} onChange={f("password")} placeholder="Minimum 6 characters" required />
              <Input label="Confirm Password" type="password" value={form.confirm} onChange={f("confirm")} placeholder="Repeat password" required />
              <Btn onClick={handleRegister} style={{ width:"100%", padding:12 }}>Next: Farm Details →</Btn>
            </>
          ) : (
            <>
              <div style={{ fontSize:12.5, color:C.muted, marginBottom:14, padding:"8px 12px", background:C.pale, borderRadius:7 }}>🌾 Step 2 of 2 — Farm Details (for personalized advice)</div>
              <Input label="District" value={form.district} onChange={f("district")} options={STATES_TN_DISTRICTS} required />
              <Input label="Total Land Size (Acres)" type="number" value={form.landSize} onChange={f("landSize")} placeholder="e.g. 3.5" hint="1 hectare = 2.47 acres" />
              <div style={{ marginBottom:14 }}>
                <label style={{ fontSize:12.5, color:C.muted, display:"block", marginBottom:6, fontWeight:500 }}>Your Crops (select all that apply)</label>
                <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
                  {CROPS_ALL.slice(0,20).map(c => (
                    <button key={c} onClick={() => cropToggle(c)} style={{
                      padding:"5px 10px", borderRadius:16, fontSize:12, cursor:"pointer",
                      background:form.crops.includes(c)?C.bg2:C.bg,
                      color:form.crops.includes(c)?"#fff":C.text,
                      border:`1.5px solid ${form.crops.includes(c)?C.bg2:C.border}`,
                    }}>{c}</button>
                  ))}
                </div>
              </div>
              <div style={{ display:"flex", gap:8 }}>
                <Btn variant="ghost" onClick={() => setStep(1)} style={{ flex:1 }}>← Back</Btn>
                <Btn onClick={handleRegister} disabled={loading} style={{ flex:2 }}>{loading ? "Creating account…" : "✅ Create Account"}</Btn>
              </div>
            </>
          )}
        </div>
        <div style={{ textAlign:"center", marginTop:14, color:"rgba(255,255,255,0.35)", fontSize:11 }}>🌿 Agro Zenith — SRM MCET, Sivagangai</div>
      </div>
    </div>
  );
}

export default AuthPage;
